insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights, owner_id) values ('block-2026-02-16-hypertrophy-flat-pyramid', 1, 'Size · Straight Sets + Supersets', 'flat-pyramid', '2026-02-16', 6, 'coach', 'A 6-week volume block: flat sets with the same reps and weight on every set, plus supersets, to build a solid base of training volume for the blocks that follow.', '[{"title": "Goal", "body": "Build a base of quality training volume: lots of controlled, moderately heavy sets for every muscle, twice a week. This was the first block of the rotation, laying the foundation that the later intensity and strength blocks build on."}, {"title": "How it works", "body": "Every set of an exercise uses the same reps and the same weight, for example 4 x 12 on the incline neutral-grip dumbbell press. After the first lift, two exercises for the same muscle are paired as a superset: do the first, rest about 10 seconds, do the second, then rest 60-90 seconds. Sessions open with lifts like the quad-focused leg press and the wide-grip shoulder press machine."}, {"title": "A days vs B days", "body": "A days use 10-12 reps per set with heavier weights; B days repeat the same exercises in the same order at 12-15 reps with lighter weights. A days lean on heavy, controlled work, while B days add extra volume and pump with less stress on the joints."}, {"title": "How to progress", "body": "Keep the same weight across all sets of an exercise. When you complete every rep of every set with good form and about one rep left in the tank, add the smallest step next time (about 1-2.5 kg upper body, 2.5-5 kg lower body). If you miss reps, keep the weight and aim for one more rep next week. Progress A and B days separately."}, {"title": "What to expect", "body": "Expect a strong pump and a steady, manageable tiredness rather than very heavy sets. Supersets make sessions feel dense and quick, and some muscle soreness is common in the first week or two. Strength rises gradually as your body adapts to the extra volume."}, {"title": "Key tips", "body": "Choose a weight you can keep for all sets; if the last set falls far short, start lighter next time. Keep the 10-second gap inside supersets short so the pairing does its job. If you repeat this block, swap nothing for six weeks so progress stays measurable."}]'::jsonb, '44b10d1d-b2db-445f-aa93-9c9793c75a3b') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
