insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights, owner_id) values ('block-2026-05-11-functional-hypertrophy-flat-pyramid', 3, 'Strength · Heavy Sets of 6-8', 'strength-hypertrophy', '2026-05-11', 6, 'coach', 'A 6-week strength block: heavy compound lifts in low-rep flat sets with longer rests, so the weights you use in the next muscle-building blocks can go up.', '[{"title": "Goal", "body": "Get stronger on the big compound lifts so the next hypertrophy blocks can be done with heavier weights. In the rotation it followed two hypertrophy blocks (volume, then intensity) and prepared the ground for the ascending-pyramid block."}, {"title": "How it works", "body": "Main lifts use flat sets of low reps with heavy weights and about 2 minutes of rest, for example 4 x 6 on the barbell bench press, the plate-loaded shoulder press machine and the hack squat. Secondary lifts like weighted chin-ups follow at 6-8 reps, and lighter accessories at 8-10 or more. There are only about five exercises per day and no supersets or drop sets."}, {"title": "A days vs B days", "body": "A days use 6 reps on the main lifts with the heaviest loads; B days repeat the same exercises at 8 reps (and accessories at 10-12) with slightly lighter weights. A days focus on pure strength, while B days add a bit more volume to support muscle growth."}, {"title": "How to progress", "body": "Keep the same weight across all sets. When you complete every set of 6 (A) or 8 (B) cleanly with about one rep in reserve, add the smallest step next time. Small, steady jumps work best at low reps; if you miss reps, repeat the weight until you own it."}, {"title": "What to expect", "body": "Sessions are slower, with longer rests and less pump, but each set feels heavy and demanding. You may notice less burn and more whole-body tiredness after the big lifts. The payoff is noticeably higher weights across the board by the end of six weeks."}, {"title": "Key tips", "body": "Take the full 2-minute rest on the main lifts so every set is done with good speed and form. Warm up with a few lighter ramp-up sets before your first working set. Use a spotter or safety pins on heavy barbell pressing and squatting."}]'::jsonb, '44b10d1d-b2db-445f-aa93-9c9793c75a3b') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
