insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights, owner_id) values ('block-2026-10-05-hypertrophy-flat-pyramid-ii', 6, 'Size · Straight Sets, Stretch Focus', 'flat-pyramid', '2026-10-05', 6, 'pt', 'Six weeks of muscle building, each muscle twice a week. Straight sets on the main lifts, at most two supersets per day, plus a reverse pyramid, a pyramid, one drop set and last-set extras like partials or myo-reps. Week 6 is lighter.', '[{"title": "Goal", "body": "Build muscle with moderate weights taken close to failure. Volume follows your history: extra side-delt and hamstring work, biceps early on arm days, about 18 weekly sets for chest and back, and every muscle gets at least one exercise loaded in a deep stretch. Exercises are the same as when the block started, so your logs carry on."}, {"title": "How it works", "body": "Main lifts come first, alone, with 2.5-3 minutes rest. Some use a reverse pyramid (heaviest set first, then lighter for more reps) or a pyramid (lighter first, heavier as reps drop). Each day has at most two supersets of non-competing muscles: first exercise, about 10 seconds, second exercise, then the full rest. Flat dumbbell press after the 30-degree press gives chest two angles. Extras like a drop set, partials, rest-pause or myo-reps are written in the exercise notes and apply to the last set only."}, {"title": "A days vs B days", "body": "A days are heavier: 8-12 reps on main lifts and 10-15 elsewhere. B days repeat the same exercises in the same order with lighter weights for 10-20 reps. The chest and back B day opens with a pyramid and the legs A day with a reverse pyramid, so each week mixes both styles. Track and progress A and B days separately."}, {"title": "How to progress", "body": "When every set reaches its target reps with clean form, add the smallest step next time; if you fall 1-2 reps short, keep the weight. In pyramids, progress each set''s weight on its own. Effort rises: week 1 about 3 reps before failure and no extras, week 2 about 2 reps, weeks 3-4 about 1-2, week 5 about 1. Week 6 is always a deload: half the sets, no extras."}, {"title": "What to expect", "body": "Week 1 should feel easy while you learn the changes. From week 2 the last-set extras add a strong burn on cables and machines, but sessions should not get longer because there are fewer supersets to set up. Expect more reps or weight on most lifts by week 5."}, {"title": "Key tips", "body": "Do extras like partials, rest-pause, myo-reps or drop sets only on the last set and only on machines, cables or isolation lifts. Never grind squats, RDLs or presses to failure. If the second machine of a superset is taken, do both as straight sets. If a movement hurts, stop it and see a qualified professional."}]'::jsonb, '44b10d1d-b2db-445f-aa93-9c9793c75a3b') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
