insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights, owner_id) values ('block-2026-11-16-strength-hypertrophy-ii', 7, 'Strength · Heavy Sets of 6-8 II', 'strength-hypertrophy', '2026-11-16', 6, 'pt', 'A 6-week strength block: one heavy top set of 4-5 reps on each A-day main lift, straight sets of 6-8 elsewhere, chest pressed at 30 then 0 degrees, one superset at most per day, and one or two last-set extras like rest-pause or partials.', '[{"title": "Goal", "body": "Get stronger on the big lifts so blocks 8 and 9 can be done with heavier weights. A small dose of heavy 4-5 rep work builds strength you can later turn into muscle, while most sets stay at 6-12 reps where growth is efficient."}, {"title": "How it works", "body": "Each A day opens with a reverse pyramid: one heavy top set (4 reps on the Smith bench and seated overhead press, 5 on the back squat), then lighter back-off sets of 6, 8 and 10, with 2.5-3 minutes rest. Other lifts are straight sets. Chest is trained at two angles: 30-degree incline dumbbell press, then the flat dumbbell press. Arm and leg days pair two non-competing exercises in one superset. One or two last-set extras per day (rest-pause, partials, myo-reps, a drop set or a slow tempo) are written in the notes."}, {"title": "A days vs B days", "body": "A days carry the heavy top set and 6-8 reps on the main lifts. B days use the same exercises with straight sets of 8-10 and a slightly lighter load, plus a pyramid on the JM press and a drop set on leg curls. A days build maximum strength; B days add volume for growth."}, {"title": "How to progress", "body": "Top sets: stop with 1-2 reps left and add the smallest step once you hit the target cleanly; back-off sets follow. Straight sets: same weight for all sets, add a step when every set is complete. Week 1: no top set (do it as a back-off set) and no extras. Weeks 2-5: full plan. Week 6 is always a deload: half the sets, no top sets, no extras."}, {"title": "What to expect", "body": "Sessions are slower, with long rests and heavy, focused sets rather than a pump. Expect more whole-body tiredness after squats and rows. By week 5 your top sets should be clearly heavier than in week 2."}, {"title": "Key tips", "body": "Warm up before every top set with 3-4 ramp sets (for example 50% x 8, 70% x 4, 85% x 2). Use safety pins or a spotter, never grind or fail a heavy set, and skip the top set if sleep or joints are bad. Use the same dumbbells for the incline and flat press. If a lift hurts, stop and see a qualified professional."}]'::jsonb, '44b10d1d-b2db-445f-aa93-9c9793c75a3b') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
