insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights, owner_id) values ('block-2026-12-28-hypertrophy-pyramid-ii', 8, 'Size · Light-to-Heavy + Supersets II', 'ascending-pyramid', '2026-12-28', 6, 'pt', 'A 6-week volume block: ascending pyramids on the lead lifts (A days finish with a 6-rep set), one or two supersets per day such as decline press with decline flies, and last-set myo-reps, partials, rest-pause or drop sets. Week 1 is lighter.', '[{"title": "Goal", "body": "Turn the strength built in block 7 into more muscle with high volume and a heavier final pyramid set. It eases back in after the holidays and leads into the reverse-pyramid intensity of block 9."}, {"title": "How it works", "body": "Each lead lift is an ascending pyramid: start light, then add weight each set as reps drop (12-10-8-6 on A days). Lead lifts are the 45-degree incline barbell press, the dumbbell shoulder press and the Smith machine squat. Each day has one or two supersets about 10 seconds apart, like decline dumbbell press with decline flies for the lower chest. Other work is straight sets, with one or two last-set extras in the notes: myo-reps on Y-raises and calves, partials on leg extensions, rest-pause on rows, and a drop set on kickbacks."}, {"title": "A days vs B days", "body": "A days run the pyramid at 12-10-8-6 with heavier supersets at about 10 reps. B days use 20-15-12-10 and higher-rep straight sets and supersets with lighter weights. A days reach a heavier top set; B days pile on reps and pump."}, {"title": "How to progress", "body": "Week 1 is lighter: stop every set about 3 reps short of failure, skip the last set of each exercise and skip all extras. From week 2, progress each pyramid set''s weight on its own, adding a small step once its reps are clean. Raise each superset exercise once all its reps are done. Week 6 is always a deload: half the sets, no extras."}, {"title": "What to expect", "body": "Week 1 should feel refreshing, not like a test. From week 2 the light opening sets work as a warm-up, effort builds to a hard final set, and supersets and myo-reps bring a strong pump. Expect your top-set weights to beat block 4 on similar lifts."}, {"title": "Key tips", "body": "Plan your weight jumps for each pyramid set before the session. Set up the bench for a superset before you start it and keep the 10-second gap short. Myo-reps: after the normal last set, rest about 5 breaths, do 4-5 reps, and repeat 3 times. If a movement hurts, stop and see a qualified professional."}]'::jsonb, '44b10d1d-b2db-445f-aa93-9c9793c75a3b') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
