insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary, insights, owner_id) values ('block-2027-02-08-hypertrophy-reverse-pyramid-iii', 9, 'Size · Heavy-to-Light + Drop Sets III', 'reverse-pyramid', '2027-02-08', 6, 'pt', 'A 6-week intensity block: reverse pyramids with a 5-rep top set on the bench, T-bar row and front squat, up to 2 drop sets per day, a curl and triceps superset, flies at 15 then 0 degrees, and last-set rest-pause or partials.', '[{"title": "Goal", "body": "Push intensity after the block 8 volume phase: lift your heaviest weights while fresh, then add fatigue with lighter sets and a few drop sets. It uses the strength from block 7 and brings in free-weight lead lifts like the barbell bench press and front squat."}, {"title": "How it works", "body": "Each lead lift is a reverse pyramid: heaviest set first, then lighter as reps rise. On A days the bench press, T-bar row and front squat open with a 5-rep top set (5-8-10-12); other lead lifts use 8-10-12-15. Drop sets (near failure, cut 20-30%, continue) are limited to two per day on machines and cables. Flies are done at 15 degrees, then flat. Arm days superset incline curls with overhead extensions. Rest-pause, partials or tempo appear in the notes."}, {"title": "A days vs B days", "body": "A days use 5-8-10-12 or 8-10-12-15 pyramids and 12+12 drop sets. B days use 10-12-15-20 and 15+15 with lighter weights. A days are about heavy loading; B days add volume and pump with less strain on the joints."}, {"title": "How to progress", "body": "Progress each pyramid set on its own, adding a small step once you hit all its reps with good form. Keep top sets 1-2 reps short of failure. For drop sets, raise the starting weight once both halves are done. Week 1: no top set (start at the second set) and no drop sets. Week 6 is always a deload: half the sets, no extras."}, {"title": "What to expect", "body": "Sessions are hard, with a strong burn during drop sets. The first heavy set of each lead lift takes focus, and the front squat and standing press need more balance than machines. Expect your lead lifts to climb steadily through the six weeks."}, {"title": "Key tips", "body": "Warm up with 3-4 ramp sets before each top set and use safety pins or a spotter. Learn the front squat and standing press with moderate weights in week 1. On incline curls, let the arms hang fully at the bottom. Use machines and cables for drop sets so weight changes are quick. If anything hurts, stop and see a qualified professional."}]'::jsonb, '44b10d1d-b2db-445f-aa93-9c9793c75a3b') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, insights = excluded.insights, updated_at = now();
